package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.SessionSsoTtlSecondsVO;

class SessionSsoTtlSecondsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of session sso ttl seconds of tenant config")
  void test_session_sso_ttl_seconds_value_holder_assign_plain_value() {
    Object holder = new Object();
    SessionSsoTtlSecondsValueHolder<Object> value = new SessionSsoTtlSecondsValueHolder<>(holder);
    Assertions.assertSame(holder, value.sessionSsoTtlSeconds(1), "Setters must return the holder");
    Assertions.assertTrue(value.getSessionSsoTtlSecondsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getSessionSsoTtlSeconds().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of session sso ttl seconds of tenant config")
  void test_session_sso_ttl_seconds_value_holder_assign_value_object() {
    Object holder = new Object();
    SessionSsoTtlSecondsValueHolder<Object> value = new SessionSsoTtlSecondsValueHolder<>(holder);
    SessionSsoTtlSecondsVO vo = SessionSsoTtlSecondsVO.from(1);
    Assertions.assertFalse(value.getSessionSsoTtlSecondsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.sessionSsoTtlSeconds(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSessionSsoTtlSecondsValue().orElseThrow());
    Assertions.assertSame(holder, value.sessionSsoTtlSeconds(Optional.empty()));
    Assertions.assertFalse(value.getSessionSsoTtlSecondsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.sessionSsoTtlSeconds(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSessionSsoTtlSecondsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of session sso ttl seconds of tenant config against the original")
  void test_session_sso_ttl_seconds_value_holder_read() {
    Object holder = new Object();
    SessionSsoTtlSecondsValueHolder<Object> value = new SessionSsoTtlSecondsValueHolder<>(holder);
    SessionSsoTtlSecondsVO vo = SessionSsoTtlSecondsVO.from(1);
    SessionSsoTtlSecondsVO other = SessionSsoTtlSecondsVO.from(1);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getSessionSsoTtlSecondsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSessionSsoTtlSeconds(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readSessionSsoTtlSeconds(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.sessionSsoTtlSeconds(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSessionSsoTtlSeconds(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSessionSsoTtlSeconds(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of session sso ttl seconds of tenant config")
  void test_session_sso_ttl_seconds_value_holder_unset() {
    Object holder = new Object();
    SessionSsoTtlSecondsValueHolder<Object> value = new SessionSsoTtlSecondsValueHolder<>(holder);
    SessionSsoTtlSecondsVO vo = SessionSsoTtlSecondsVO.from(1);
    value.sessionSsoTtlSeconds(vo);
    Assertions.assertSame(holder,
        value.unsetSessionSsoTtlSecondsIfMatches("sessionSsoTtlSeconds_other"));
    Assertions.assertTrue(value.getSessionSsoTtlSecondsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSessionSsoTtlSecondsIfMatches("sessionSsoTtlSeconds"));
    Assertions.assertFalse(value.getSessionSsoTtlSecondsValue().isPresent(),
        "The field name must clear the value");
    value.sessionSsoTtlSeconds(vo);
    Assertions.assertSame(holder, value.unsetSessionSsoTtlSeconds());
    Assertions.assertFalse(value.getSessionSsoTtlSecondsValue().isPresent(),
        "Unset must clear the value");
  }
}
